import{H as e,ht as t,nt as n,tt as r}from"./chunks/framework.CXX_0q1Z.js";var i=JSON.parse(`{"title":"Commands and Permissions","description":"","frontmatter":{},"headers":[],"relativePath":"en/modules/storage/commands.md","filePath":"en/modules/storage/commands.md","lastUpdated":0}`),a={name:`en/modules/storage/commands.md`};function o(e,i,a,o,s,c){return t(),r(`div`,null,[...i[0]||=[n(`<h1 id="commands-and-permissions" tabindex="-1">Commands and Permissions <a class="header-anchor" href="#commands-and-permissions" aria-label="Permalink to “Commands and Permissions”">​</a></h1><p>EmakiStorage&#39;s main command is <code>/emakistorage</code>, aliased to <code>/estorage</code>. Examples in the docs use <code>/estorage</code>.</p><p>Running it with no arguments opens your own warehouse and requires <code>emakistorage.use</code> (<code>emakistorage.admin</code> also passes). Admin subcommands all require <code>emakistorage.admin</code>; <code>reload</code> and <code>debug</code> have their own dedicated permissions which <code>emakistorage.admin</code> can also replace.</p><h2 id="command-list" tabindex="-1">Command List <a class="header-anchor" href="#command-list" aria-label="Permalink to “Command List”">​</a></h2><table tabindex="0"><thead><tr><th>Command</th><th>Permission</th><th>Description</th></tr></thead><tbody><tr><td><code>/estorage</code></td><td><code>emakistorage.use</code></td><td>Opens your own warehouse. Players only.</td></tr><tr><td><code>/estorage help</code></td><td>No extra check</td><td>Shows help.</td></tr><tr><td><code>/estorage open &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>Opens a target player&#39;s warehouse as an admin. The sender must be a player.</td></tr><tr><td><code>/estorage slot grant &lt;player&gt; &lt;amount&gt;</code></td><td><code>emakistorage.admin</code></td><td>Adjusts the target&#39;s granted slot pool. A negative <code>amount</code> reclaims slots.</td></tr><tr><td><code>/estorage stacklimit player &lt;player&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>Sets the target&#39;s player-level per-slot ceiling.</td></tr><tr><td><code>/estorage stacklimit slot &lt;player&gt; &lt;slot&gt; &lt;limit&gt;</code></td><td><code>emakistorage.admin</code></td><td>Sets the entry-level ceiling of one logical slot.</td></tr><tr><td><code>/estorage info &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>Prints the capacity breakdown, page count, <code>stackLimit</code>, sort mode and total amount.</td></tr><tr><td><code>/estorage export &lt;player&gt;</code></td><td><code>emakistorage.admin</code></td><td>Exports the warehouse as readable YAML into <code>exports/export-&lt;uuid&gt;.yml</code>.</td></tr><tr><td><code>/estorage autopickup [on|off|toggle]</code></td><td><code>emakistorage.autopickup</code></td><td>Manages your personal auto-pickup switch. <code>on</code> (<code>true</code> / <code>enable</code> are equivalent) enables it; <code>off</code> (<code>false</code> / <code>disable</code> are equivalent) disables it; omitting the argument or passing anything else toggles. Also requires <code>auto_pickup.enabled: true</code>, otherwise it reports the feature as disabled.</td></tr><tr><td><code>/estorage reload</code></td><td><code>emakistorage.reload</code> or <code>emakistorage.admin</code></td><td>Reloads config, language and GUI templates, then reports the loaded template count.</td></tr><tr><td><code>/estorage debug ...</code></td><td><code>emakistorage.debug</code> or <code>emakistorage.admin</code></td><td>Manages debug modules. Available modules are <code>storage</code> and <code>chat_input</code>; subcommands come from CoreLib&#39;s DebugCommand.</td></tr></tbody></table><h2 id="examples" tabindex="-1">Examples <a class="header-anchor" href="#examples" aria-label="Permalink to “Examples”">​</a></h2><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/estorage</span></span>
<span class="line"><span>/estorage help</span></span>
<span class="line"><span>/estorage open Steve</span></span>
<span class="line"><span>/estorage slot grant Steve 10</span></span>
<span class="line"><span>/estorage slot grant Steve -5</span></span>
<span class="line"><span>/estorage stacklimit player Steve 100000</span></span>
<span class="line"><span>/estorage stacklimit player Steve max</span></span>
<span class="line"><span>/estorage stacklimit player Steve 10k</span></span>
<span class="line"><span>/estorage stacklimit slot Steve 3 5000</span></span>
<span class="line"><span>/estorage info Steve</span></span>
<span class="line"><span>/estorage export Steve</span></span>
<span class="line"><span>/estorage autopickup on</span></span>
<span class="line"><span>/estorage autopickup</span></span>
<span class="line"><span>/estorage reload</span></span>
<span class="line"><span>/estorage debug storage on</span></span></code></pre></div><h2 id="argument-formats" tabindex="-1">Argument Formats <a class="header-anchor" href="#argument-formats" aria-label="Permalink to “Argument Formats”">​</a></h2><table tabindex="0"><thead><tr><th>Argument</th><th>Accepted input</th><th>Notes</th></tr></thead><tbody><tr><td><code>&lt;amount&gt;</code> (slot grant)</td><td>Decimal integer, may be negative</td><td>Negative values reclaim granted slots.</td></tr><tr><td><code>&lt;limit&gt;</code> (stacklimit)</td><td>Decimal number, compact units (<code>k</code> <code>m</code> <code>b</code> <code>t</code> <code>p</code> <code>e</code>), <code>max</code>, <code>0</code></td><td><code>max</code> resolves to <code>Long.MAX_VALUE</code>. <code>0</code> is the explicit &quot;restore inheritance&quot; form: <code>0</code> at entry level falls back to the player level, and <code>0</code> at player level falls back to <code>capacity.default_stack_limit</code>. Any other result <code>&lt;= 0</code>, plus overflow, is rejected outright rather than truncated, so a mistyped figure never silently becomes a different ceiling.</td></tr><tr><td><code>&lt;slot&gt;</code></td><td>Logical slot index (0-based)</td><td>When that slot holds no entry the command reports &quot;slot empty&quot; and no entry is created.</td></tr></tbody></table><h2 id="write-operations-require-the-target-online" tabindex="-1">Write Operations Require the Target Online <a class="header-anchor" href="#write-operations-require-the-target-online" aria-label="Permalink to “Write Operations Require the Target Online”">​</a></h2><p><code>slot grant</code> and <code>stacklimit</code> are refused outright when the target is offline, reporting <code>command.target_offline</code>. The reason is that these operations mutate the in-memory storage object: writing directly into an unloaded save would race the player&#39;s next login and could overwrite or discard the change.</p><p>For online targets the write is dispatched to that player&#39;s own region thread, not the caller&#39;s. If the target&#39;s storage is still loading, the command reports <code>general.data_loading</code>; retry shortly.</p><p>Read-only commands do not share this restriction: <code>info</code> and <code>export</code> use the snapshot read path, which loads from disk when necessary, so they work for offline players too. <code>open &lt;player&gt;</code> also works for offline targets.</p><h2 id="permission-nodes" tabindex="-1">Permission Nodes <a class="header-anchor" href="#permission-nodes" aria-label="Permalink to “Permission Nodes”">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Default</th><th>Scope</th></tr></thead><tbody><tr><td><code>emakistorage.use</code></td><td><code>true</code></td><td>Opening your own warehouse.</td></tr><tr><td><code>emakistorage.unlock.purchase</code></td><td><code>true</code></td><td>Using paid expansion in the GUI. Also requires <code>unlock.purchase_enabled: true</code>.</td></tr><tr><td><code>emakistorage.autopickup</code></td><td><code>true</code></td><td>Using <code>/estorage autopickup</code> and the auto-pickup feature itself.</td></tr><tr><td><code>emakistorage.reload</code></td><td><code>op</code></td><td>Using <code>/estorage reload</code>. Can be replaced by <code>emakistorage.admin</code>.</td></tr><tr><td><code>emakistorage.debug</code></td><td><code>op</code></td><td>Using <code>/estorage debug ...</code>. Can be replaced by <code>emakistorage.admin</code>.</td></tr><tr><td><code>emakistorage.admin</code></td><td><code>op</code></td><td>Using <code>open</code>, <code>slot</code>, <code>stacklimit</code>, <code>info</code> and <code>export</code>, and replacing the dedicated reload/debug permissions.</td></tr></tbody></table><h2 id="numeric-tier-permissions" tabindex="-1">Numeric Tier Permissions <a class="header-anchor" href="#numeric-tier-permissions" aria-label="Permalink to “Numeric Tier Permissions”">​</a></h2><p>The following two permissions are <strong>numeric tiers</strong>. They are not declared in <code>paper-plugin.yml</code>; simply grant the node with a numeric suffix.</p><table tabindex="0"><thead><tr><th>Permission prefix</th><th>Effect</th><th>Resolution rule</th></tr></thead><tbody><tr><td><code>emakistorage.slots.&lt;n&gt;</code></td><td>Adds <code>n</code> slots</td><td>Scans every effective permission and takes the <strong>highest</strong> numeric suffix. Tiers do not stack.</td></tr><tr><td><code>emakistorage.stacklimit.&lt;n&gt;</code></td><td>Provides a player-level per-slot ceiling of <code>n</code></td><td>Also takes the highest value.</td></tr></tbody></table><p>Neither supports <strong>wildcards</strong>: a node such as <code>emakistorage.slots.*</code> is skipped. Some permission plugins expand a wildcard into &quot;holds every n&quot;, which would silently push the player to the maximum tier, so the implementation only accepts a purely numeric suffix and ignores suffixes containing <code>.</code> or non-digits.</p><p>Common LuckPerms examples:</p><div class="language-text"><button title="Copy code" data-copied="Copied" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>/lp group default permission set emakistorage.use true</span></span>
<span class="line"><span>/lp group default permission set emakistorage.unlock.purchase true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.slots.100 true</span></span>
<span class="line"><span>/lp group vip permission set emakistorage.stacklimit.100000 true</span></span>
<span class="line"><span>/lp group admin permission set emakistorage.admin true</span></span></code></pre></div><h2 id="reload-behaviour" tabindex="-1">reload Behaviour <a class="header-anchor" href="#reload-behaviour" aria-label="Permalink to “reload Behaviour”">​</a></h2><p><code>/estorage reload</code> performs the following work:</p><ol><li>Releases missing default resources, controlled by <code>config.yml &gt; release_default_data</code>.</li><li>Re-reads <code>config.yml</code>, <code>lang/*.yml</code>, <code>unlock_costs.yml</code> and <code>gui/storage_gui.yml</code>.</li><li>Recomputes the GUI layout for the new <code>gui.storage_rows</code>.</li><li>Reports how many GUI templates were loaded.</li></ol><p>A <code>gui.storage_rows</code> outside 1–5 is clamped with a console warning, see <a href="./configuration.html">Configuration</a>.</p><h2 id="common-failure-reasons" tabindex="-1">Common Failure Reasons <a class="header-anchor" href="#common-failure-reasons" aria-label="Permalink to “Common Failure Reasons”">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>Explanation</th></tr></thead><tbody><tr><td><code>Player not found</code></td><td>The name does not match exactly and no cached offline player exists.</td></tr><tr><td><code>Player ... is offline, cannot perform this write</code></td><td><code>slot grant</code> and <code>stacklimit</code> targets must be online.</td></tr><tr><td><code>Storage data is still loading, try again shortly</code></td><td>The target is online but their storage has not finished loading.</td></tr><tr><td><code>Slot empty</code></td><td>The logical slot given to <code>stacklimit slot</code> currently holds no entry.</td></tr><tr><td><code>stacklimit</code> argument rejected</td><td>The parsed value is <code>&lt;= 0</code> (other than <code>0</code> itself) or out of <code>long</code> range. Use a positive integer, a compact unit, <code>max</code> or <code>0</code>.</td></tr><tr><td>Warehouse window fails to open</td><td>The GUI template was not loaded or failed to parse; check console warnings.</td></tr></tbody></table>`,27)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};